@@ -41,6 +41,6 @@
-    // JVMTI and JFR code use mark words for marking objects for their needs.
-    // On this path, we can encounter the "marked" object, but with null
-    // fwdptr. That object is still not forwarded, and we need to return
-    // the object itself.
-    HeapWord* fwdptr = (HeapWord*) mark.clear_lock_bits().to_pointer();
-    return (fwdptr != nullptr) ? cast_to_oop(fwdptr) : obj;
+    // Historically, JVMTI and JFR used mark words for marking objects
+    // for their needs, without regard for GC. This path is now unreachable:
+    // incompatible JFR code is disabled with Shenandoah. Assert paranoidly.
+    HeapWord* fwd = (HeapWord*) mark.clear_lock_bits().to_pointer();
+    assert(fwd != nullptr, "Sanity: forwardee must be set");
+    return cast_to_oop(fwd);
@@ -118,0 +118,1 @@
+      assert(fwd != nullptr, "Sanity: forwarding pointer must be set");
@@ -131,4 +132,10 @@
-  markWord w = obj->mark();
-  assert(!w.is_marked(), "Must not be forwarded");
-  assert(w.age() <= markWord::max_age, "Age is in bounds");
-  return w.age();
+  markWord mark = obj->mark();
+  if (!mark.is_marked()) {
+    // Object has trustworthy mark.
+    assert(mark.age() <= markWord::max_age, "Age is in bounds");
+    return mark.age();
+  } else {
+    // Otherwise resolve the forwardee and try again.
+    oop fwd = get_forwardee_raw(obj, mark);
+    return age(fwd);
+  }
@@ -140,4 +147,4 @@
-  markWord w = obj->mark();
-  if (!w.is_marked()) {
-    w = w.set_age(MIN2(markWord::max_age, w.age() + add));
-    obj->set_mark(w);
+  markWord mark = obj->mark();
+  if (!mark.is_marked()) {
+    mark = mark.set_age(MIN2(markWord::max_age, mark.age() + add));
+    obj->set_mark(mark);

@@ -115,2 +115,2 @@
-          shenandoah_assert_not_in_cset_except(addr, value, ShenandoahForwarding::is_self_forwarded(value));
-          shenandoah_assert_not_forwarded_except(addr, value, ShenandoahForwarding::is_self_forwarded(value));
+          shenandoah_assert_not_in_cset_except(addr, value, ShenandoahHeap::heap()->cancelled_gc());
+          shenandoah_assert_not_forwarded_except(addr, value, ShenandoahHeap::heap()->cancelled_gc());
